function ledgerNote(item){if(item.notes_edited)return String(item.notes||'');const notes=String(item.notes||'').trim(),legacy=String(item.purpose||'').trim();return !legacy||notes===legacy||notes.startsWith(legacy+'\n')?notes:legacy+(notes?'\n'+notes:'');}
let accountDocumentDraft=null;
