const modal = $('#modal'), drawer = $('#drawer');
const money = n => (Number(n || 0) / 100).toLocaleString('zh-CN', {minimumFractionDigits:2, maximumFractionDigits:2});
const moneyShort = n => Math.abs(Number(n || 0)) >= 100000000 ? `${(n / 1000000).toFixed(1)}万` : money(n);
const number = n => Number(n || 0).toLocaleString('zh-CN');
const cents = value => { const s = String(value || '').trim(); if (!/^\d+(\.\d{1,2})?$/.test(s)) throw Error('金额请填写非负数字，最多两位小数'); const [a,b=''] = s.split('.'); const n = Number(a)*100+Number(b.padEnd(2,'0')); if (!Number.isSafeInteger(n)) throw Error('金额过大'); return n; };
function today() { const parts = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()); return ['year','month','day'].map(t=>parts.find(p=>p.type===t).value).join('-'); }
const fmtDate = v => String(v || '').slice(0,10) || '—';
const shortDate = v => fmtDate(v).replace(/-/g,'.');
const ago = v => { if (!v) return '—'; return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v)); };
const storeName = id => db.stores?.find(x=>x.id===id)?.name || (id ? '未知门店' : '装配区 / 本仓');
const comp = id => db.components?.find(x=>x.id===id);
const serial = id => comp(id)?.serial || '—';
const componentKind = k => labels[k] || k;
const badge = (status, custom) => `<span class="badge ${['claimed','repair'].includes(status)?'orange':['scrapped','disassembled'].includes(status)?'gray':status==='spare'?'blue':['income','expense'].includes(status)?status:''}">${esc(custom || labels[status] || status)}</span>`;
const amount = item => `<span class="${item.direction === 'income' ? 'amount-income' : 'amount-expense'}">${item.direction === 'income' ? '+' : '−'} ¥ ${money(item.amount_cents)}</span>`;
const actionBtn = (act,text,id='',type='',cls='') => `<button type="button" class="btn small ${cls}" data-act="${esc(act)}" data-id="${esc(id)}" data-type="${esc(type)}">${text}</button>`;
const empty = (text='还没有记录',desc='从右上角添加第一条记录开始。',i='box') => `<div class="empty">${icon(i)}<strong>${esc(text)}</strong><p>${esc(desc)}</p></div>`;
function url(path, params={}) { const u = new URL(path, location.origin); u.searchParams.set('profile',profile); Object.entries(params).forEach(([k,v])=>{if(v!==undefined&&v!==null)u.searchParams.set(k,v);}); return u.pathname+u.search; }
async function api(path, data, opts={}) {
  const method = opts.method || (data === undefined ? 'GET' : 'POST');
  const headers = {}; if(method !== 'GET') headers['X-CSRF-Token'] = session.csrf || '';
  const args={method,headers,credentials:'same-origin',cache:'no-store'};
  if(data instanceof FormData) args.body=data; else if(data !== undefined) {headers['Content-Type']='application/json';args.body=JSON.stringify(data);}
  let response;
  try {response=await fetch(url(path,opts.params),args);} catch(e){throw Error('无法连接本地服务，请重新双击桌面“小车台账”入口。');}
  if(!response.ok){let body;try{body=await response.json();}catch{body={error:`操作失败（${response.status}）`};}if(response.status===401){session.unlocked=false;db={};closeDrawer();closeModal({force:true});render();}throw Error(body.error || '操作失败');}
  return opts.blob ? response.blob() : response.status===204 ? {} : response.json();
}
function toast(text,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=text;$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
function normalize(data){['stores','batches','components','vehicles','ledger','shipments','movements','history','attachments','credentials'].forEach(k=>data[k] ||= []);data.summary ||= {};return data;}
async function refresh(){const data=await api('/api/state');db=normalize(data);render();if(detailContext)renderDetail(detailContext.type,detailContext.id);$('#save-status').textContent=`已保存至本机 · ${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())}`;}
async function load(){try{session=await api('/api/session');updateChrome();if(session.unlocked)await refresh();else {db={};render();}}catch(e){$('#main').innerHTML=`<div class="auth-card"><div class="auth-logo">${icon('info')}</div><h1 class="auth-title">暂时无法打开台账</h1><p class="auth-subtitle">${esc(e.message)}</p><button class="btn primary" data-act="retry">重新连接</button></div>`;}}
async function command(action,data,requestId){if(!requestId&&busy&&modal.open){const fingerprint=JSON.stringify([action,data]);if(modalActionFingerprint!==fingerprint){modalActionFingerprint=fingerprint;modalRequestId=crypto.randomUUID();}requestId=modalRequestId;}const result=await api('/api/action',{action,data,request_id:requestId||crypto.randomUUID()});try{await refresh();}catch(e){toast('操作已保存，但页面刷新未完成。请点击右上角刷新按钮查看。',true);}return result;}
function updateChrome(){if(!routes.some(x=>x[0]===route))route='overview';$('#nav').innerHTML=routes.map(([id,title,i])=>`<button type="button" class="nav-item ${route===id?'active':''}" data-route="${id}" aria-label="${title}" title="${title}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${route===id?'<span class="nav-arrow">›</span>':''}</button>`).join('');$('#breadcrumb').textContent=routes.find(x=>x[0]===route)[1];$$('[data-profile]').forEach(b=>{b.classList.toggle('active',b.dataset.profile===profile);b.setAttribute('aria-pressed',String(b.dataset.profile===profile));});$('#lock-button').innerHTML=`${icon('lock')} ${profile==='live'?'锁定台账':'正式台账需解锁'}`;$('#today').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date());}
function go(next){if(!closeModal())return;route=next;filters={};location.hash=next;closeDrawer();render();$('#main').focus({preventScroll:true});}
function header(title,subtitle,actions='',eyebrow='WORKSPACE'){return `<div class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="header-actions">${actions}</div></div>`;}
function demoNotice(){return profile==='demo'?`<div class="demo-notice"><span>${icon('info')}<strong>正在查看演示台账</strong>　示例数据可自由试用，与正式记录独立保存。</span><button type="button" class="notice-action" data-act="switch-live">开始正式记账 →</button></div>`:'';}
function render(){hideHoverPreview();updateChrome();if(!session.unlocked){renderAuth();return;}const pages={overview:renderOverview,ledger:renderLedger,inventory:renderInventory,vehicles:renderVehicles,shipments:renderShipments,stores:renderStores,settings:renderSettings};$('#main').innerHTML=pages[route]();}
function metric(label,value,foot,i,featured=false){return `<div class="metric${featured?' featured':''}"><div class="metric-label">${label}</div><div class="metric-icon">${icon(i)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function chart(){const months=[];const d=new Date(`${today()}T00:00:00+08:00`);for(let n=5;n>=0;n--){const m=new Date(d.getFullYear(),d.getMonth()-n,1);months.push(`${m.getFullYear()}-${String(m.getMonth()+1).padStart(2,'0')}`);}const rows=months.map(m=>({month:m,income:db.ledger.filter(x=>!x.voided&&x.direction==='income'&&x.date.startsWith(m)).reduce((a,x)=>a+x.amount_cents,0),expense:db.ledger.filter(x=>!x.voided&&x.direction==='expense'&&x.date.startsWith(m)).reduce((a,x)=>a+x.amount_cents,0)}));const max=Math.max(10000,...rows.flatMap(x=>[x.income,x.expense]));return `<svg class="bar-chart" viewBox="0 0 620 200" role="img" aria-label="最近六个月收入和支出柱状图">${[0,1,2,3].map(i=>`<line class="chart-line" x1="45" x2="611" y1="${24+i*44}" y2="${24+i*44}"/><text class="chart-label" x="0" y="${27+i*44}">${Math.round(max*(3-i)/3/100).toLocaleString()}</text>`).join('')}${rows.map((r,i)=>{const x=69+i*90;return `<rect x="${x}" y="${156-r.income/max*132}" width="17" height="${Math.max(r.income?3:0,r.income/max*132)}" rx="3" fill="#c96863"><title>${esc(r.month)} 收入 ¥${money(r.income)}</title></rect><rect x="${x+24}" y="${156-r.expense/max*132}" width="17" height="${Math.max(r.expense?3:0,r.expense/max*132)}" rx="3" fill="#b5d7ae"><title>${esc(r.month)} 支出 ¥${money(r.expense)}</title></rect><text class="chart-label" text-anchor="middle" x="${x+20}" y="184">${Number(r.month.slice(5))}月</text>`;}).join('')}</svg>`;}
function renderOverview(){const s=db.summary;const active=db.ledger.filter(x=>!x.voided);const totalComponents=db.components.length;const installed=db.components.filter(x=>x.status==='installed').length;const claimed=db.components.filter(x=>x.status==='claimed').length;const available=db.components.filter(x=>x.status==='available').length;const ratio=totalComponents?available/totalComponents*100:0;const ratio2=totalComponents?(available+installed)/totalComponents*100:0;return header('每一台小车，都有一本账。','库存、收支与门店交付，一处清楚掌握。',`<button class="btn" data-act="export">${icon('download')} 备份台账</button><button class="btn primary" data-act="ledger-new">${icon('plus')} 记一笔收支</button>`,'BUSINESS OVERVIEW')+demoNotice()+`<div class="metric-grid">${metric('累计实际收入',`<span class="amount-income"><span class="currency">¥</span>${moneyShort(s.income_cents)}</span>`,`${active.filter(x=>x.direction==='income').length} 笔到账记录 · 以实际收款为准`,'in',true)}${metric('累计实际支出',`<span class="amount-expense"><span class="currency">¥</span>${moneyShort(s.expense_cents)}</span>`,`${active.filter(x=>x.direction==='expense').length} 笔支出记录 · 含采购与研发`,'out')}${metric('收支差额',`<span class="currency">¥</span>${moneyShort(s.balance_cents)}`,'实际收入 − 实际支出','money')}${metric('已交付小车',`${number(s.shipped)}<small>台</small>`,`覆盖 ${number(s.store_count??db.stores.length)} 家门店 · 待出货 ${number(s.ready)} 台`,'car')}</div><div class="dashboard-middle"><section class="panel"><div class="panel-head"><h2>收支走势 <small>近六个月</small></h2><div class="legend"><span><i></i>收入</span><span><i class="expense"></i>支出</span></div></div><div class="chart-wrap">${chart()}</div></section><section class="panel"><div class="panel-head"><h2>配件与整车</h2><button class="btn link" data-route="inventory">查看库存 ${icon('arrow')}</button></div><div class="inventory-overview"><div class="inventory-summary"><div class="ring" style="background:conic-gradient(#527b56 0 ${ratio}%,#d1dfb3 ${ratio}% ${ratio2}%,#edf0e5 ${ratio2}%)"><div class="ring-center">${totalComponents}<small>配件总套数</small></div></div><div class="inventory-stat-lines"><div><span><i></i>在库可用</span><b>${available}<small> 套</small></b></div><div><span><i class="light"></i>已安装</span><b>${installed}<small> 套</small></b></div><div><span><i class="gray"></i>已领用待装车</span><b>${claimed}<small> 套</small></b></div></div></div><div class="inventory-bottom"><div>PCBA 可用 <b>${number(s.pcba_available)}</b></div><div>结构件可用 <b>${number(s.frame_available)}</b></div></div></div></section></div><div class="dashboard-bottom"><section class="panel"><div class="panel-head"><h2>最近收支 <small>每一笔都有凭据</small></h2><button class="btn link" data-route="ledger">全部账目 ${icon('arrow')}</button></div>${active.length?ledgerTable([...active].sort((a,b)=>b.date.localeCompare(a.date)||b.created_at.localeCompare(a.created_at)).slice(0,5),true):empty('还没有收支记录','按分类记录实际收入和支出。','ledger')}</section><section class="panel"><div class="panel-head"><h2>常用操作</h2><span class="subtle">QUICK ACTIONS</span></div><div class="quick-grid"><button class="quick-item" data-act="batch-new" data-type="pcba">${icon('box')}<span>PCBA入库<small>逐块扫描 PCBA 编号</small></span></button><button class="quick-item" data-act="batch-new" data-type="frame">${icon('box')}<span>结构件入库<small>逐套扫描车架编号</small></span></button><button class="quick-item" data-act="outbound" data-type="pcba">${icon('scan')}<span>PCBA 出库<small>扫码 · 确认 · 记录</small></span></button><button class="quick-item" data-act="outbound" data-type="frame">${icon('scan')}<span>结构件出库<small>精确到每一个车架号</small></span></button><button class="quick-item quick-item-wide" data-act="assemble">${icon('car')}<span>组成成品车<small>车架号绑定 PCBA 号</small></span></button></div>${db.stores.slice(0,2).map(s=>`<div class="store-mini"><div class="store-icon">${icon('store')}</div><div><strong>${esc(s.name)}</strong><small>${esc(s.contact||'门店档案')} · ${db.vehicles.filter(v=>v.store_id===s.id&&v.status==='shipped').length} 台小车</small></div><button class="btn link" data-act="detail" data-type="store" data-id="${s.id}">查看 →</button></div>`).join('')}${!db.stores.length?`<div class="store-mini"><span class="muted">还没有门店</span><button class="btn link" data-act="store-new">添加第一家门店 →</button></div>`:''}</section></div>`;}
function filterSearch(placeholder){return `<div class="search-box">${icon('search')}<input type="search" data-filter="search" value="${esc(filters.search||'')}" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></div>`;}
function options(items,current,placeholder){return (placeholder!==undefined?`<option value="">${esc(placeholder)}</option>`:'')+items.map(([v,t])=>`<option value="${esc(v)}" ${String(current??'')===String(v)?'selected':''}>${esc(t)}</option>`).join('');}
function filterSelect(key,items,placeholder){return `<select class="filter-select" data-filter="${key}" aria-label="${esc(placeholder)}">${options(items,filters[key],placeholder)}</select>`;}
function filterDates(){return `<label class="sr-only" for="date-from">开始日期</label><input class="filter-input" id="date-from" type="date" data-filter="date_from" value="${esc(filters.date_from||'')}" title="开始日期"><span class="muted">—</span><label class="sr-only" for="date-to">结束日期</label><input class="filter-input" id="date-to" type="date" data-filter="date_to" value="${esc(filters.date_to||'')}" title="结束日期">`;}
function matches(value){return !filters.search || String(value).toLowerCase().includes(filters.search.toLowerCase());}
function dateMatches(value){return (!filters.date_from||value>=filters.date_from)&&(!filters.date_to||value<=filters.date_to);}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="data-table ${cls}"><thead><tr>${headers.map(h=>`<th${h[0]==='>'?' class="right"':''}>${esc(h[0]==='>'?h.slice(1):h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function ledgerTable(rows,compact=false){return table(compact?['分类 / 备注','日期','>金额']:['收支分类','备注','日期','>金额','附件','操作'],rows.map(x=>{const files=db.attachments.filter(a=>a.owner_type==='ledger'&&a.owner_id===x.id);return `<tr class="${x.voided?'voided':''}"><td><div class="row-title"><span class="transaction-icon ${x.direction}">${icon(x.direction==='income'?'in':'out')}</span><div><button class="table-link primary-text ${x.direction==='income'?'amount-income':'amount-expense'}" data-act="detail" data-type="ledger" data-id="${x.id}">${esc(x.category)}</button><div class="secondary">${esc(compact?ledgerNote(x):labels[x.direction])}${x.voided?' · 已作废':''}</div></div></div></td>${compact?'':`<td class="ledger-note-cell">${esc(ledgerNote(x)||'—')}</td>`}<td class="muted">${shortDate(x.date)}</td><td class="number">${amount(x)}</td>${compact?'':`<td><button class="btn link ledger-attachments" data-act="detail" data-type="ledger" data-id="${x.id}" ${files.length?`data-hover-ledger="${x.id}"`:''} aria-label="${files.length} 份附件${files.length?'，悬停预览':''}">${icon('file')} ${files.length} 份</button></td><td>${x.voided?badge('scrapped','已作废'):actionBtn('ledger-edit','编辑',x.id)}</td>`}</tr>`; }),compact?'compact':'');}
function renderLedger(){const rows=db.ledger.filter(x=>(!filters.direction||x.direction===filters.direction)&&(!filters.category||x.category===filters.category)&&dateMatches(x.date)&&matches(`${x.category} ${ledgerNote(x)}`)).sort((a,b)=>b.date.localeCompare(a.date)||b.created_at.localeCompare(a.created_at));const valid=rows.filter(x=>!x.voided),income=valid.filter(x=>x.direction==='income').reduce((n,x)=>n+x.amount_cents,0),expense=valid.filter(x=>x.direction==='expense').reduce((n,x)=>n+x.amount_cents,0);const categories=[...new Set([...ledgerCategories.income,...ledgerCategories.expense,...db.ledger.map(x=>x.category)])];return header('收支账本','按分类记录收入与支出，截图和发票随账保存。',`<button class="btn primary" data-act="ledger-new">${icon('plus')} 记一笔收支</button>`,'INCOME & EXPENSE')+`<div class="mini-stats"><div class="mini-stat finance-income">筛选内收入<b class="amount-income">¥ ${money(income)}</b></div><div class="mini-stat finance-expense">筛选内支出<b class="amount-expense">¥ ${money(expense)}</b></div><div class="mini-stat">收支差额<b>¥ ${money(income-expense)}</b></div></div><section class="panel"><div class="toolbar">${filterSearch('搜索分类或备注')}${filterSelect('direction',[['income','收入'],['expense','支出']],'全部收支')}${filterSelect('category',categories.map(c=>[c,c]),'全部分类')}${filterDates()}<span class="spacer"></span><span class="result-count">共 ${rows.length} 笔</span></div>${rows.length?ledgerTable(rows):empty('没有符合条件的账目','可以调整筛选条件，或记一笔新的收支。','ledger')}</section>`;}
function renderInventory(){const selectedKind=filters.kind||'';const comps=db.components.filter(x=>(!selectedKind||x.kind===selectedKind)&&(!filters.status||x.status===filters.status)&&matches(`${x.serial} ${x.notes} ${storeName(x.store_id)}`));const batches=db.batches.filter(x=>(!selectedKind||x.kind===selectedKind)&&dateMatches(x.date)&&matches(`${x.date} ${x.notes} ${db.components.filter(c=>c.batch_id===x.id).map(c=>c.serial).join(' ')}`)).sort((a,b)=>b.date.localeCompare(a.date));const available=k=>db.components.filter(c=>c.kind===k&&c.status==='available').length;return header('入库与库存','逐套登记编号，掌握每一套配件的数量与去向。',`<button class="btn" data-act="outbound" data-type="pcba">${icon('scan')} PCBA 出库</button><button class="btn" data-act="outbound" data-type="frame">${icon('scan')} 结构件出库</button><button class="btn primary" data-act="batch-new" data-type="pcba">${icon('plus')} PCBA入库</button><button class="btn primary" data-act="batch-new" data-type="frame">${icon('plus')} 结构件入库</button>`,'INTAKE & INVENTORY')+`<div class="mini-stats"><div class="mini-stat">PCBA 在库可用<b>${available('pcba')} <small>套</small></b></div><div class="mini-stat">结构件在库可用<b>${available('frame')} <small>套</small></b></div><div class="mini-stat">已领用待装车<b>${db.components.filter(c=>c.status==='claimed').length} <small>套</small></b></div><div class="mini-stat">累计入库数量<b>${db.components.length} <small>套</small></b></div></div><div class="tab-bar"><button class="tab ${inventoryTab==='components'?'active':''}" data-tab="components">单套库存</button><button class="tab ${inventoryTab==='batches'?'active':''}" data-tab="batches">入库记录</button><button class="tab ${inventoryTab==='movements'?'active':''}" data-tab="movements">库存流水</button></div><section class="panel"><div class="toolbar">${filterSearch(inventoryTab==='batches'?'搜索入库日期、编号或备注':'扫描或搜索配件编号')}${filterSelect('kind',[['pcba','PCBA'],['frame','结构件 / 车架']],'全部类型')}${inventoryTab==='components'?filterSelect('status',Object.entries(labels).filter(([k])=>['available','claimed','installed','spare','repair','scrapped'].includes(k)),'全部状态'):filterDates()}<span class="spacer"></span><span class="result-count">共 ${inventoryTab==='components'?comps.length:inventoryTab==='batches'?batches.length:db.movements.length} 条</span></div>${inventoryTab==='components'?componentsTable(comps):inventoryTab==='batches'?batchesTable(batches):movementsTable(db.movements.filter(m=>dateMatches(m.date)&&(!selectedKind||comp(m.component_id)?.kind===selectedKind)&&matches(`${serial(m.component_id)} ${m.notes}`)).slice().reverse())}</section>`;}
function componentsTable(rows){if(!rows.length)return empty('没有符合条件的配件','点击“入库”，逐套扫描编号后即可管理。');return table(['配件编号','类型','当前状态','当前位置','入库记录','操作'],rows.map(c=>`<tr><td><button class="table-link mono" data-act="detail" data-type="component" data-id="${c.id}">${esc(c.serial)}</button></td><td>${badge(c.kind,c.kind==='frame'?'结构件 / 车架':'PCBA')}</td><td>${badge(c.status)}</td><td>${esc(c.status==='available'?'本仓':c.store_id?storeName(c.store_id):c.status==='claimed'?'装配区':'—')}</td><td><button class="btn link" data-act="detail" data-type="batch" data-id="${esc(c.batch_id)}">${shortDate(db.batches.find(b=>b.id===c.batch_id)?.date)}</button></td><td>${actionBtn('detail','查看',c.id,'component')}${c.status==='available'?` ${actionBtn('outbound','出库',c.id,c.kind)}`:''}${['claimed','spare','repair'].includes(c.status)?` ${actionBtn('component-return','退库',c.id)}`:''}</td></tr>`));}
function batchesTable(rows){if(!rows.length)return empty('还没有入库记录','选择配件类型，并扫描这批配件的编号。');return table(['入库日期','配件类型','入库数量','备注','操作'],rows.map(b=>`<tr><td>${shortDate(b.date)}</td><td>${componentKind(b.kind)}</td><td>${b.quantity??db.components.filter(c=>c.batch_id===b.id).length} 套</td><td class="ledger-note-cell">${esc(b.notes||'—')}</td><td>${actionBtn('detail','查看',b.id,'batch')}</td></tr>`));}
function movementsTable(rows){if(!rows.length)return empty('还没有库存流水','每次入库、出库和处理都会自动留下记录。','history');return table(['日期','配件编号','操作','状态变化','门店 / 去向','说明'],rows.map(m=>`<tr><td class="muted">${shortDate(m.date)}</td><td><button class="table-link mono" data-act="detail" data-type="component" data-id="${m.component_id}">${esc(serial(m.component_id))}</button></td><td>${esc(eventLabels[m.action]||labels[m.action]||m.action)}</td><td>${esc(labels[m.from_status]||m.from_status||'—')} → ${esc(labels[m.to_status]||m.to_status)}</td><td>${esc(storeName(m.store_id))}</td><td class="muted">${esc(m.notes||'—')}</td></tr>`));}
function renderVehicles(){const rows=db.vehicles.filter(v=>(!filters.status||v.status===filters.status)&&(!filters.store_id||v.store_id===filters.store_id)&&matches(`${v.serial} ${v.pcba_serial||serial(v.pcba_id)} ${storeName(v.store_id)}`));return header('车辆档案','以车架号为主线，记录配对、交付与每一次更换。',`<button class="btn" data-act="ship">${icon('truck')} 整车出货</button><button class="btn primary" data-act="assemble">${icon('plus')} 组成成品车</button>`,'VEHICLE RECORDS')+`<section class="panel"><div class="toolbar">${filterSearch('搜索车架号、PCBA 号或门店')}${filterSelect('status',[['ready','待出货'],['shipped','已出货'],['disassembled','已拆解']],'全部状态')}${filterSelect('store_id',db.stores.map(s=>[s.id,s.name]),'全部门店')}<span class="spacer"></span><span class="result-count">共 ${rows.length} 台</span></div>${vehiclesTable(rows)}</section>`;}
function vehiclesTable(rows,compact=false){if(!rows.length)return empty('还没有车辆档案','先将 PCBA 和结构件领用出库，再以车架号完成配对。','car');return table(compact?['车架号','PCBA 号','状态']:['车架号','当前 PCBA 号','状态','所属门店','登记日期','操作'],rows.map(v=>`<tr><td><button class="table-link mono" data-act="detail" data-type="vehicle" data-id="${v.id}">${esc(v.serial)}</button></td><td class="mono">${esc(v.pcba_serial||serial(v.pcba_id))}</td><td>${badge(v.status)}</td>${compact?'':`<td>${esc(storeName(v.store_id))}</td><td class="muted">${shortDate(v.created_at)}</td><td>${actionBtn('detail','详情',v.id,'vehicle')}${v.status!=='disassembled'?` ${actionBtn('replace','换板',v.id)} ${actionBtn(v.status==='ready'?'ship':'transfer',v.status==='ready'?'出货':'转店',v.id)}`:''}</td>`}</tr>`),compact?'compact':'');}
function renderShipments(){const rows=db.shipments.filter(s=>(!filters.store_id||s.store_id===filters.store_id)&&(!filters.kind||s.kind===filters.kind)&&dateMatches(s.date)&&matches(`${storeName(s.store_id)} ${s.notes} ${(s.items||[]).map(x=>x.serial).join(' ')}`)).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.created_at.localeCompare(a.created_at));return header('出货记录','整车与备件交付有据可查，门店转移保留来路。',`<button class="btn" data-act="spare-transfer">${icon('transfer')} 备件调拨</button><button class="btn primary" data-act="ship">${icon('plus')} 整车出货</button>`,'DELIVERY & TRANSFER')+`<section class="panel"><div class="toolbar">${filterSearch('搜索门店、编号或出货备注')}${filterSelect('kind',[['vehicle','整车出货'],['spare','备件出货'],['transfer','门店调拨']],'全部类型')}${filterSelect('store_id',db.stores.map(s=>[s.id,s.name]),'全部门店')}${filterDates()}<span class="spacer"></span><span class="result-count">共 ${rows.length} 笔</span></div>${rows.length?table(['出货日期','门店','类型','交付清单','状态','操作'],rows.map(s=>`<tr class="${s.voided?'voided':''}"><td>${shortDate(s.date)}</td><td><button class="table-link" data-act="detail" data-type="store" data-id="${s.store_id}">${esc(storeName(s.store_id))}</button></td><td>${badge(s.kind)}</td><td><span class="primary-text">${(s.items||[]).length} ${(s.items||[]).some(i=>i.kind==='vehicle')?'台':'套'}</span><div class="secondary mono">${esc((s.items||[]).slice(0,2).map(i=>i.serial).join('、'))}${(s.items||[]).length>2?' …':''}</div></td><td>${badge(s.voided?'scrapped':'shipped',s.voided?'已撤销':'已完成')}</td><td>${actionBtn('detail','查看',s.id,'shipment')}</td></tr>`)):empty('还没有出货记录','整车出货、备件发店和调拨记录都会在这里汇总。','truck')}</section>`;}
function renderStores(){const rows=db.stores.filter(s=>matches(`${s.name} ${s.code||''} ${s.contact} ${s.phone} ${s.address} ${s.notes}`));return header('门店档案','车辆、账号与安装资料，跟着门店一起归档。',`<button class="btn primary" data-act="store-new">${icon('plus')} 添加门店</button>`,'STORE WORKSPACE')+`<div class="toolbar" style="padding:0 0 20px;border:0">${filterSearch('搜索店名、编码、联系人、电话或地址')}<span class="result-count">共 ${rows.length} 家门店</span></div>${rows.length?`<div class="store-grid">${rows.map(s=>{const cars=db.vehicles.filter(v=>v.store_id===s.id&&v.status==='shipped').length;const fileCount=db.attachments.filter(a=>a.owner_type==='store'&&a.owner_id===s.id).length;return `<article class="store-card"><div class="store-card-header"><div class="store-card-icon">${icon('store')}</div><div><h2>${esc(s.name)}</h2><small class="store-code">${esc(s.code||'未设置编码')}</small></div></div><div class="store-card-info"><div>${icon('person')}${esc(s.contact||'尚未填写联系人')}${s.phone?' · '+esc(s.phone):''}</div><div>${icon('pin')}${esc(s.address||'尚未填写安装地址')}</div></div><div class="store-card-footer"><div><b>${cars}</b><span>台小车 · ${fileCount} 份安装资料</span></div><button class="btn link" data-act="detail" data-type="store" data-id="${s.id}">进入档案 →</button></div></article>`;}).join('')}</div>`:empty('添加第一家门店','记录小车去向，也记录现场安装和账号备忘。','store')}`;}
function renderSettings(){return header('设置与备份','妥善保存台账，也为重要信息留一份备份。','','SETTINGS & BACKUP')+demoNotice()+`<div class="settings-grid"><section class="panel settings-card"><div class="setting-icon">${icon('download')}</div><h2>完整台账备份</h2><p>导出当前台账的账目、库存、车辆历史、门店资料与全部有效附件。门店账号仍保持加密，备份内不包含明文密码或恢复密钥。</p><button class="btn primary" data-act="export">${icon('download')} 导出完整备份</button><div class="setting-info"><span>当前台账</span><strong>${profile==='demo'?'演示台账':'正式台账'}</strong></div></section><section class="panel settings-card"><div class="setting-icon">${icon('upload')}</div><h2>从备份恢复</h2><p>先检查文件完整性，再替换当前台账。正式台账备份需要原密码或恢复密钥；恢复失败时不会覆盖当前记录。</p><button class="btn" data-act="restore">${icon('upload')} 选择备份并恢复</button><div class="setting-info"><span>演示与正式数据</span><strong>独立目录 · 分开恢复</strong></div></section><section class="panel settings-card"><div class="setting-icon">${icon('shield')}</div><h2>账号与解锁保护</h2><p>${profile==='live'?'门店账号和密码已启用加密保存。修改解锁密码不影响已保存资料；恢复密钥请另行保管。':'演示台账只用于试用。录入真实门店账号前，请切换正式台账并设置解锁密码。'}</p><div class="actions">${profile==='live'?`<button class="btn" data-act="password-change">${icon('key')} 修改解锁密码</button><button class="btn soft" data-act="lock">${icon('lock')} 立即锁定</button>`:`<button class="btn primary" data-act="switch-live">设置正式台账 ${icon('arrow')}</button>`}</div><div class="setting-info"><span>本地服务</span><strong>只监听本机地址</strong></div></section><section class="panel settings-card"><div class="setting-icon">${icon('box')}</div><h2>数据与使用说明</h2><p>当前共 ${db.ledger.length} 笔收支、${db.components.length} 套配件、${db.vehicles.filter(v=>v.status!=='disassembled').length} 台车辆、${db.stores.length} 家门店。普通账目和附件保存在本地磁盘，门店账号信息单独加密。</p><div class="actions"><button class="btn" data-act="refresh">${icon('refresh')} 刷新数据</button><button class="btn danger" data-act="shutdown">停止本地服务</button></div><div class="setting-info"><span>默认币种与时间</span><strong>人民币 CNY · 北京时间</strong></div></section></div>`;}

function field(name,label,value='',opts={}){const type=opts.type||'text';const req=opts.required?' required':'';const common=`name="${esc(name)}" id="field-${esc(name)}"${req}${opts.placeholder?` placeholder="${esc(opts.placeholder)}"`:''}${opts.min!==undefined?` min="${opts.min}"`:''}${opts.max!==undefined?` max="${opts.max}"`:''}${opts.step?` step="${opts.step}"`:''}${opts.autocomplete?` autocomplete="${opts.autocomplete}"`:''}`;let input;if(type==='textarea')input=`<textarea ${common} rows="${opts.rows||3}">${esc(value)}</textarea>`;else if(type==='select')input=`<select ${common}>${options(opts.options||[],value,opts.placeholder)}</select>`;else input=`<input type="${type}" ${common} value="${type==='file'?'':esc(value)}"${opts.multiple?' multiple':''}${opts.accept?` accept="${esc(opts.accept)}"`:''}>`;return `<div class="field${opts.full?' full':''}"><label for="field-${esc(name)}">${esc(label)}${opts.required?'<span class="required">*</span>':''}</label>${input}${opts.help?`<small>${esc(opts.help)}</small>`:''}</div>`;}
function formError(message,root=modal){const box=$('.form-error',root);if(box){box.textContent=message;box.classList.add('visible');box.scrollIntoView({block:'nearest'});}else toast(message,true);}
function showForm({title,description='',fields='',submit='保存',onSubmit,onOpen,wide=false,note='',danger=false}){clearModalPreviews();hideHoverPreview();destroyAttachmentPicker();delete modal.dataset.secretView;uploadRequestIds=new Map();fileDigests=new WeakMap();modalRequestId=crypto.randomUUID();modalActionFingerprint='';modal.setAttribute('aria-label',title);modal.classList.toggle('wide',wide);$('#modal-content').innerHTML=`<form id="dialog-form"><div class="modal-head"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button type="button" class="icon-button" data-close="modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body"><div class="form-error" role="alert"></div>${note?`<div class="form-note">${note}</div>`:''}<div class="field-grid">${fields}</div></div><div class="modal-footer"><button type="button" class="btn" data-close="modal">取消</button><button class="btn ${danger?'danger':'primary'}" type="submit">${esc(submit)}</button></div></form>`;modalSubmit=onSubmit;if(!modal.open)modal.showModal();if(onOpen)onOpen($('#dialog-form'));setTimeout(()=>{const form=$('#dialog-form');const first=$(form?.dataset.focusTarget||'input:not([type="hidden"]),select,textarea',modal);first?.focus();},30);}
function closeModal({force=false}={}){if(!force&&accountDocumentDraft?.dirty&&!window.confirm('账号备忘有未保存的修改，确定放弃这些修改吗？'))return false;accountDocumentDraft=null;clearModalPreviews();hideHoverPreview();destroyAttachmentPicker();uploadRequestIds.clear();fileDigests=new WeakMap();delete modal.dataset.secretView;modalRequestId='';if(modal.open)modal.close();modalSubmit=null;recoverySecret='';$('#modal-content').innerHTML='';return true;}
