function confirmAction(title,note,handler,opts={}){showForm({title,description:note,fields:opts.reason===false?'':field('reason','操作原因','',{required:true,full:true,type:'textarea',placeholder:'请输入原因，作为历史记录保留'}),submit:opts.submit||'确认操作',danger:opts.danger??true,onSubmit:async(fd)=>{await handler(fd.get('reason')||'');toast(opts.success||'操作已完成');}});}
function fdObj(fd){return Object.fromEntries(fd.entries());}
function storeOptions(){return db.stores.map(s=>[s.id,s.name]);}
function dateField(){return field('date','发生日期',today(),{type:'date',required:true});}
