function section(title,body,actions=''){return `<section class="drawer-section"><h3>${title}<span class="actions">${actions}</span></h3>${body}</section>`;}
function detailGrid(items){return `<dl class="detail-grid">${items.map(([k,v,full])=>`<div class="${full?'full':''}"><dt>${esc(k)}</dt><dd>${v||'—'}</dd></div>`).join('')}</dl>`;}
function timeline(items){return items.length?`<div class="timeline">${items.map(h=>`<div class="timeline-item"><small>${shortDate(h.date||h.created_at)}</small><strong>${esc(eventLabels[h.event||h.action]||labels[h.event||h.action]||h.event||h.action)}</strong><p>${esc([h.old_pcba_serial&&`原 PCBA：${h.old_pcba_serial}`,h.new_pcba_serial&&`新 PCBA：${h.new_pcba_serial}`,h.from_store_id&&`原门店：${storeName(h.from_store_id)}`,h.to_store_id&&`新门店：${storeName(h.to_store_id)}`,h.from_status&&`${labels[h.from_status]||h.from_status} → ${labels[h.to_status]||h.to_status}`,h.notes].filter(Boolean).join('\n'))}</p></div>`).join('')}</div>`:`<p class="muted">暂无历史记录</p>`;}
function fileList(type,id){const files=db.attachments.filter(a=>a.owner_type===type&&a.owner_id===id);return files.length?`<div class="file-list">${files.map(a=>`<div class="file-item" data-hover-attachment="${a.id}" ${inlineMime(a)?'tabindex="0"':''}><div class="file-symbol">${icon(a.mime?.startsWith('image/')?'image':'file')}</div><div class="file-info"><strong title="${esc(a.filename)}">${esc(type==='store'?(a.slot||a.filename):a.filename)}</strong><small>${esc(type==='store'?a.filename+' · ':'')}${a.size>1048576?(a.size/1048576).toFixed(1)+' MB':Math.max(1,Math.round(a.size/1024))+' KB'} · ${shortDate(a.created_at)}${a.notes?' · '+esc(a.notes):''}</small></div><div class="file-actions">${type==='store'?`<button class="icon-button" data-act="attachment-replace" data-id="${a.id}" title="替换此项文件" aria-label="替换文件">${icon('refresh')}</button>`:''}<button class="icon-button" data-act="attachment-preview" data-id="${a.id}" title="预览" aria-label="预览文件">${icon('eye')}</button><a class="icon-button" href="${url('/api/attachments/'+a.id,{download:1})}" title="下载" aria-label="下载文件">${icon('download')}</a><button class="icon-button" data-act="attachment-delete" data-id="${a.id}" title="删除" aria-label="删除文件">${icon('trash')}</button></div></div>`).join('')}</div>`:`<p class="muted">还没有附件</p>`;}
function credentialList(storeId){const store=db.stores.find(s=>s.id===storeId),legacy=db.credentials.some(c=>c.store_id===storeId);return `<div class="account-document-summary">${icon('lock')}<div><strong>账号备忘文档</strong><p>${store?.has_document?'内容已加密保存，打开后可自由编辑。':legacy?'已有旧版账号，打开后会整理成可自由编辑的文字。':'一份空白文档，账号、密码和说明都可以按自己的方式填写。'}</p><small>仅在你打开时读取正文</small></div></div>`;}
