    const base=page.getViewport({scale:1}),available=Math.max(100,$('.pdf-canvas-scroll',view.root).clientWidth-20),cssScale=Math.min(available/base.width,2),pixelRatio=Math.min(window.devicePixelRatio||1,2),scale=Math.min(cssScale*pixelRatio,4096/Math.max(base.width,base.height),Math.sqrt(12000000/(base.width*base.height)));
    const viewport=page.getViewport({scale});canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);canvas.style.width=`${Math.ceil(viewport.width/pixelRatio)}px`;canvas.style.height=`${Math.ceil(viewport.height/pixelRatio)}px`;canvas.setAttribute('aria-label',`PDF 第 ${pageNumber} 页`);
