function hoverAttachments(target){return target?.dataset.hoverLedger?db.attachments.filter(a=>a.owner_type==='ledger'&&a.owner_id===target.dataset.hoverLedger):[];}
async function showHoverPreview(target,expanded=false,attachmentIndex=0){
  if(!target||busy)return;
  if(hoverTrigger===target&&hoverPreview&&!hoverPreview.hidden&&attachmentIndex===hoverAttachmentIndex){clearTimeout(hoverCloseTimer);if(expanded){positionHoverPreview(true);redrawPdfPreviews(hoverPreview);}return;}
  const collection=hoverAttachments(target);if(target.dataset.hoverLedger&&!collection.length)return;
  const index=collection.length?Math.max(0,Math.min(attachmentIndex,collection.length-1)):0;
  hideHoverPreview();const token=hoverGeneration;hoverTrigger=target;hoverAttachmentIndex=index;
  try{
    let filename,mime='',source='',previewBlob,download='';const pendingId=target.dataset.previewPending;
    if(pendingId){const entry=attachmentPicker?.entries.find(e=>e.id===pendingId);if(!entry?.mime)return;filename=entry.file.name;mime=entry.mime;source=entry.url;previewBlob=entry.previewBlob;}
    else {
      const attachment=collection.length?collection[index]:db.attachments?.find(a=>a.id===target.dataset.hoverAttachment);
      if(!attachment||(!collection.length&&!inlineMime(attachment)))return;
      filename=attachment.filename;download=url('/api/attachments/'+attachment.id,{download:1});await ensureUnlocked();
      if(inlineMime(attachment)){const blob=await api('/api/attachments/'+attachment.id,undefined,{blob:true});mime=await sniffPreviewMime(blob);if(token!==hoverGeneration||!target.isConnected)return;if(mime){previewBlob=new Blob([blob],{type:mime});if(mime.startsWith('image/')){source=objectURL(previewBlob);hoverBlobURL=source;}}}
    }
    if(token!==hoverGeneration||!target.isConnected)return;
    const el=getHoverElement(),host=modal.open?modal:drawer.open?drawer:document.body;if(el.parentElement!==host)host.append(el);
    const controls=collection.length>1?`<div class="hover-file-controls"><button type="button" class="btn small" data-act="hover-file-previous" aria-label="上一份附件" ${index===0?'disabled':''}>上一份</button><span>附件 ${index+1} / ${collection.length}</span><button type="button" class="btn small" data-act="hover-file-next" aria-label="下一份附件" ${index===collection.length-1?'disabled':''}>下一份</button></div>`:'';
    el.innerHTML=`<div class="hover-preview-head"><strong title="${esc(filename)}">${esc(filename)}</strong>${mime?'<button type="button" class="btn link small" data-act="hover-expand">放大预览</button>':''}<button type="button" class="icon-button" data-act="hover-close" aria-label="关闭快速预览">${icon('close')}</button></div>${controls}<div class="hover-preview-body">${mime==='application/pdf'?'<div class="pdf-hover-host"></div>':mime?`<img src="${source}" alt="${esc(filename)}">`:`<div class="hover-preview-unsupported">${icon('file')}<p>此格式请下载后查看</p><a class="btn small" href="${download}">下载原文件</a></div>`}</div><div class="hover-preview-foot">${mime==='application/pdf'?'PDF 页面预览，可滚动或翻页':mime?'图片预览':'附件资料'} · 移开鼠标后关闭</div>`;
    el.hidden=false;positionHoverPreview(expanded);if(el.showPopover){if(!el.matches(':popover-open'))el.showPopover();}else if(modal.open)modal.append(el);else if(drawer.open)drawer.append(el);
    if(mime==='application/pdf')await mountPdfPreview($('.pdf-hover-host',el),previewBlob);
  }catch(e){if(token!==hoverGeneration)return;hideHoverPreview();if(session.unlocked)toast(e.message,true);}
}
async function stepHoverAttachment(step){if(!hoverTrigger)return;const target=hoverTrigger,expanded=hoverPreview?.dataset.expanded==='true',items=hoverAttachments(target),index=hoverAttachmentIndex+step;if(index>=0&&index<items.length)await showHoverPreview(target,expanded,index);}
function queueHoverPreview(target){if(hoverTrigger===target&&hoverPreview&&!hoverPreview.hidden){clearTimeout(hoverCloseTimer);return;}clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>showHoverPreview(target),220);}
function previewTarget(target){return target?.closest?.('[data-hover-attachment],[data-preview-pending],[data-hover-ledger]');}
document.addEventListener('pointerover',e=>{const target=previewTarget(e.target);if(target&&!target.contains(e.relatedTarget))queueHoverPreview(target);});
document.addEventListener('pointerout',e=>{const target=previewTarget(e.target);if(target&&!target.contains(e.relatedTarget))scheduleHoverClose();});
document.addEventListener('focusin',e=>{const target=previewTarget(e.target);if(target)queueHoverPreview(target);});
document.addEventListener('focusout',e=>{if(previewTarget(e.target))scheduleHoverClose();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&hoverPreview&&!hoverPreview.hidden){e.preventDefault();e.stopPropagation();hideHoverPreview();}},true);
document.addEventListener('paste',e=>{if(!attachmentPicker||!modal.open||busy)return;const items=[...(e.clipboardData?.items||[])].filter(item=>item.kind==='file'&&item.type.startsWith('image/'));if(!items.length)return;const files=items.map(item=>item.getAsFile()).filter(Boolean).map((file,index)=>new File([file],`粘贴图片-${Date.now()}-${index+1}.${file.type.split('/')[1]?.replace('jpeg','jpg')||'png'}`,{type:file.type,lastModified:Date.now()}));if(files.length){e.preventDefault();addPendingFiles(files).catch(error=>formError(error.message));}});
for(const type of ['dragenter','dragover'])document.addEventListener(type,e=>{if(![...(e.dataTransfer?.types||[])].includes('Files'))return;e.preventDefault();if(attachmentPicker&&modal.open&&!busy){e.dataTransfer.dropEffect='copy';$('.attachment-dropzone',attachmentPicker.root).classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{if(!e.relatedTarget&&attachmentPicker)$('.attachment-dropzone',attachmentPicker.root).classList.remove('drag-over');});
document.addEventListener('drop',e=>{if(![...(e.dataTransfer?.types||[])].includes('Files'))return;e.preventDefault();if(attachmentPicker&&modal.open){$('.attachment-dropzone',attachmentPicker.root).classList.remove('drag-over');if(!busy)addPendingFiles([...(e.dataTransfer.files||[])]).catch(error=>formError(error.message));}else toast('请先打开收支或添加附件窗口，再拖入文件。',true);});
window.addEventListener('resize',hideHoverPreview);
document.addEventListener('scroll',event=>{if(!hoverPreview?.contains(event.target))hideHoverPreview();},true);

function attachmentForm(type,id,replaceId=''){
  const original=db.attachments.find(a=>a.id===replaceId),uploadedFiles=new Set();
  showForm({title:replaceId?'替换安装资料':type==='store'?'添加安装资料':'添加附件',description:replaceId?'新文件保存成功后替换旧文件，不保留旧版。':'选择文件、拖入文件，或直接粘贴图片；悬停可预览。',fields:(type==='store'?field('slot','资料项名称',original?.slot||'',{required:true,full:true,placeholder:'例如：安装图、运行地图、安全池参数',help:'同一门店下，同名资料项会替换原文件。'}):'')+attachmentPickerHTML(type==='store'?'资料文件':'图片 / PDF / 其他附件')+field('notes','文件备注',original?.notes||'',{type:'textarea',full:true}),submit:replaceId?'确认替换':'上传并保存',note:original?`正在替换：${esc(original.filename)}`:'',onOpen:form=>bindAttachmentPicker(form,{multiple:type!=='store'}),onSubmit:async fd=>{if(attachmentPicker?.checks)throw Error('附件正在读取，请稍后保存');const entries=attachmentPicker?.entries.slice()||[];if(!entries.length)throw Error('请先选择文件、拖入文件或粘贴图片');const errors=[];for(const entry of entries){if(uploadedFiles.has(entry.id))continue;try{await uploadFile(type,id,entry.file,type==='store'?String(fd.get('slot')||''):`attachment-${entry.id}`,String(fd.get('notes')||''));uploadedFiles.add(entry.id);entry.uploaded=true;renderPendingFiles();}catch(e){errors.push(`${entry.file.name}：${e.message}`);}}try{await refresh();}catch(e){toast('已保存的附件保留在本机，请刷新页面查看。',true);}if(errors.length)throw Error('部分附件未上传，重试只处理未成功的文件：'+errors.join('；'));toast('文件已保存到本机');}});
}
async function previewAttachment(id){
  hideHoverPreview();destroyAttachmentPicker();clearModalPreviews();const a=db.attachments.find(x=>x.id===id);if(!a)return;
  modal.classList.add('wide');modal.setAttribute('aria-label','附件预览');$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${esc(a.filename)}</h2><p>${esc(a.notes||'附件预览')}</p></div><button type="button" class="icon-button" data-close="modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body"><div class="attachment-preview-main"><div class="loading">正在读取附件…</div></div></div><div class="modal-footer"><a class="btn primary" href="${url('/api/attachments/'+id,{download:1})}">${icon('download')} 下载原文件</a></div>`;modalSubmit=null;if(!modal.open)modal.showModal();
  const container=$('.attachment-preview-main',modal),viewProfile=profile;
  if(!inlineMime(a)){container.innerHTML=`<div class="empty">${icon('file')}<strong>此格式请下载后查看</strong><p>文件只作为资料保存，不会在页面内执行。</p></div>`;return;}
  await ensureUnlocked();const blob=await api('/api/attachments/'+id,undefined,{blob:true}),mime=await sniffPreviewMime(blob);if(!container.isConnected||viewProfile!==profile||!modal.open)return;
  if(!mime){container.innerHTML='<div class="empty"><strong>此格式请下载后查看</strong></div>';return;}
  const safeBlob=new Blob([blob],{type:mime});if(mime==='application/pdf'){container.classList.add('preview-pdf-canvas');await mountPdfPreview(container,safeBlob);}else {const source=objectURL(safeBlob);container.dataset.previewObjectUrl=source;container.innerHTML=`<img class="preview-image" src="${source}" alt="${esc(a.filename)}">`;}
}
async function accountDocumentForm(storeId){const sourceProfile=profile;await ensureUnlocked();const data=await api('/api/stores/'+encodeURIComponent(storeId)+'/document');if(sourceProfile!==profile||!session.unlocked||detailContext?.type!=='store'||detailContext.id!==storeId)return;let fingerprint='',requestId=crypto.randomUUID();const text=data.text||'';data.text='';showForm({title:'账号备忘',description:'这是一份自由文档，可以按自己的方式记录账号、密码与说明。保存后加密保存在本机。',wide:true,note:data.legacy_imported?'旧版账号已整理成文字供你编辑，保存后以这份文档为准；原始记录继续保留。':'',fields:`<div class="field full account-document-field"><label for="store-document-text">账号备忘文档</label><textarea id="store-document-text" name="document_text" class="account-document-text" maxlength="40000" rows="16" spellcheck="false" autocomplete="off" aria-label="账号备忘文档">${esc(text)}</textarea><small>支持自由换行，最多 40000 个字符。</small></div>`,submit:'保存文档',onSubmit:async fd=>{const value=String(fd.get('document_text')||'');if(Array.from(value).length>40000)throw Error('账号备忘最多 40000 个字符');const input=$('#store-document-text',modal),draft=accountDocumentDraft;input.readOnly=true;try{const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)),next=[...new Uint8Array(bytes)].map(n=>n.toString(16).padStart(2,'0')).join('');if(next!==fingerprint){fingerprint=next;requestId=crypto.randomUUID();}await api('/api/stores/'+encodeURIComponent(storeId)+'/document',{text:value,request_id:requestId});if(accountDocumentDraft===draft)draft.dirty=false;try{await refresh();}catch{toast('文档已加密保存，请刷新页面查看最新状态。',true);}toast('账号备忘文档已保存');}finally{if(input.isConnected)input.readOnly=false;}}});modal.dataset.secretView='document';accountDocumentDraft={dirty:false};$('#store-document-text',modal).addEventListener('input',()=>{if(accountDocumentDraft)accountDocumentDraft.dirty=true;});}
async function ensureUnlocked(){if(profile==='demo')return;session=await api('/api/session');if(!session.unlocked){db={};closeModal({force:true});closeDrawer();render();throw Error('台账已锁定，请重新解锁后查看账号。');}}
async function idleLock(){if(profile!=='live'||!session.unlocked)return;const request=api('/api/auth/lock',{}).catch(()=>{});session.unlocked=false;db={};closeModal({force:true});closeDrawer();render();toast('台账因长时间未操作而锁定。');await request;}
async function copyValue(value){try{await navigator.clipboard.writeText(value);toast('已复制到剪贴板');}catch{throw Error('浏览器未允许自动复制，请选中内容手动复制。');}}

function renderAuth(mode=''){const setup=!session.initialized&&!mode, recover=mode==='recover';$('#main').innerHTML=header('正式台账','本机保存，解锁后继续你的量产记录。','','PRIVATE WORKSPACE')+`<section class="auth-card"><div class="auth-logo">${icon(recover?'key':'lock')}</div><h1 class="auth-title">${recover?'使用恢复密钥':setup?'创建你的正式台账':'解锁正式台账'}</h1><p class="auth-subtitle">${recover?'输入单独保管的恢复密钥，并设置一个新的解锁密码。':setup?'从一份空台账开始。设置解锁密码后，我们会生成恢复密钥供你单独保管。':'门店账号已加密保存。请输入密码继续，数据仍保留在这台电脑上。'}</p><form id="auth-form" data-mode="${recover?'recover':setup?'setup':'unlock'}"><div class="form-error" role="alert"></div><div class="field-grid">${recover?field('recovery_key','恢复密钥','',{required:true,full:true,autocomplete:'off',placeholder:'粘贴你单独保存的恢复密钥'}):''}${field('password',setup||recover?'设置解锁密码':'解锁密码','',{type:'password',required:true,full:true,autocomplete:setup||recover?'new-password':'current-password',help:setup||recover?'至少 8 个字符，请使用容易记住的长密码。':''})}${setup||recover?field('confirm_password','再次输入密码','',{type:'password',required:true,full:true,autocomplete:'new-password'}):''}</div><button class="btn primary" type="submit">${icon(recover?'key':'lock')} ${recover?'恢复并重设密码':setup?'创建正式台账':'解锁台账'}</button></form><div class="auth-links"><button type="button" data-act="switch-demo">先查看演示台账</button>${session.initialized?`<button type="button" data-act="${recover?'auth-unlock':'auth-recover'}">${recover?'返回密码解锁':'忘记密码？使用恢复密钥'}</button>`:''}</div></section>`;}
function showRecovery(key){recoverySecret=key;modal.classList.remove('wide');$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>请单独保存恢复密钥</h2><p>忘记密码时，它可以帮助你恢复已加密的门店账号。</p></div></div><div class="modal-body"><div class="form-note">恢复密钥不会自动保存在台账或普通备份中。请下载后放到独立位置，或抄写保存。</div><div class="recovery-key">${esc(key)}</div><div class="actions"><button class="btn primary" type="button" data-act="recovery-download">${icon('download')} 下载恢复密钥</button><button class="btn" type="button" data-act="recovery-copy">${icon('copy')} 复制密钥</button></div><label class="inline-choice" style="margin-top:22px"><input type="checkbox" id="recovery-ack">我已在台账以外的位置保存恢复密钥</label></div><div class="modal-footer"><button class="btn primary" type="button" id="recovery-done" data-act="recovery-done" disabled>已保存，继续</button></div>`;modalSubmit=null;if(!modal.open)modal.showModal();$('#recovery-ack').addEventListener('change',e=>{$('#recovery-done').disabled=!e.target.checked;});}
function downloadBlob(blob,name){const link=document.createElement('a');const objectUrl=URL.createObjectURL(blob);link.href=objectUrl;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),10000);}
function passwordChangeForm(){showForm({title:'修改解锁密码',description:'原来的门店账号和恢复密钥继续有效。',fields:field('old_password','当前解锁密码','',{type:'password',required:true,full:true,autocomplete:'current-password'})+field('password','新的解锁密码','',{type:'password',required:true,full:true,autocomplete:'new-password',help:'至少 8 个字符'})+field('confirm_password','再次输入新密码','',{type:'password',required:true,full:true,autocomplete:'new-password'}),onSubmit:async(fd)=>{if(String(fd.get('password')).length<8)throw Error('新密码至少需要 8 个字符');if(fd.get('password')!==fd.get('confirm_password'))throw Error('两次输入的新密码不一致');await api('/api/auth/change',{old_password:fd.get('old_password'),password:fd.get('password')});toast('解锁密码已更新');}});}
function restoreForm(){showForm({title:'从完整备份恢复',description:`将替换当前${profile==='demo'?'演示':'正式'}台账，请先导出当前数据作为备份。`,note:'恢复会校验数据库及附件完整性。失败不会覆盖当前记录；演示备份与正式备份不能混用。',fields:field('file','选择台账备份文件','',{type:'file',accept:'.zip',required:true,full:true})+(profile==='live'?field('password','备份原解锁密码','',{type:'password',full:true,autocomplete:'off',help:'填写原密码或下方恢复密钥中的一项。'})+field('recovery_key','备份恢复密钥','',{full:true,autocomplete:'off'}):'')+`<label class="inline-choice field full"><input type="checkbox" name="confirm" required>我确认使用此备份替换当前台账</label>`,submit:'检查并恢复',danger:true,onSubmit:async(fd)=>{const form=new FormData();for(const key of ['file','password','recovery_key']){const v=fd.get(key);if(v)form.set(key,v);}await api('/api/restore',form);closeDrawer();session=await api('/api/session');if(session.unlocked)await refresh();else {db={};render();}toast('备份已恢复'+(profile==='live'?'，请重新解锁':''));}});}

async function dispatch(act,el){const id=el?.dataset.id||'',type=el?.dataset.type||'';switch(act){case'choose-attachments':if(attachmentPicker&&!busy)$('input[type=file]',attachmentPicker.root).click();break;case'attachment-remove':removePendingFile(id);break;case'pending-preview':{const target=$(`[data-preview-pending="${id}"]`,modal);if(target)await showHoverPreview(target,true);break;}case'hover-expand':positionHoverPreview(true);redrawPdfPreviews(hoverPreview);break;case'hover-file-previous':await stepHoverAttachment(-1);break;case'hover-file-next':await stepHoverAttachment(1);break;case'hover-close':hideHoverPreview();break;case'retry':return load();case'refresh':await refresh();toast('数据已刷新');break;case'ledger-new':ledgerForm();break;case'ledger-edit':ledgerForm(id);break;case'ledger-void':confirmAction('作废这笔账目','原记录保留，但不再参与收入、支出统计。',reason=>command('ledger.void',{id,reason}),{submit:'确认作废'});break;case'store-new':storeForm();break;case'store-edit':storeForm(id);break;case'batch-new':batchForm(type);break;case'outbound':outboundForm(type||'pcba',id);break;case'assemble':assembleForm();break;case'ship':shipmentForm('ship',id);break;case'transfer':shipmentForm('transfer',id);break;case'replace':replaceForm(id);break;case'spare-transfer':spareTransferForm(id);break;case'component-return':componentReturnForm(id);break;case'component-dispose':componentDisposeForm(id);break;case'disassemble':confirmAction('撤销这次装车','仅未出货、没有后续变动的小车可撤销装车。两套配件回到已领用待装车状态。',reason=>command('vehicle.disassemble',{id,date:today(),notes:reason}),{submit:'确认撤销装车'});break;case'shipment-void':confirmAction('撤销这次出货','仅关联车辆或配件没有后续操作时可撤销，原记录和撤销原因会保留。',reason=>command('shipment.void',{id,reason}),{submit:'确认撤销出货'});break;case'detail':openDetail(type,id);break;case'attachment-new':attachmentForm(type,id);break;case'attachment-replace':{const a=db.attachments.find(x=>x.id===id);if(a)attachmentForm(a.owner_type,a.owner_id,id);break;}case'attachment-preview':await previewAttachment(id);break;case'attachment-delete':confirmAction('删除这个附件','删除后将无法在台账中查看；如需保留请先下载。',async()=>{await api('/api/attachments/delete',{id});await refresh();},{reason:false,submit:'确认删除'});break;case'account-document':await accountDocumentForm(id);break;case'switch-live':await switchProfile('live');break;case'switch-demo':await switchProfile('demo');break;case'lock':if(profile==='demo'){await switchProfile('live');return;}await api('/api/auth/lock',{});db={};session.unlocked=false;closeDrawer();closeModal({force:true});render();break;case'auth-recover':renderAuth('recover');break;case'auth-unlock':renderAuth();break;case'recovery-download':downloadBlob(new Blob([`小车台账 · 恢复密钥\n\n${recoverySecret}\n\n请在台账以外的位置单独保管。不要与他人分享。\n生成日期：${today()}\n`],{type:'text/plain;charset=utf-8'}),`小车台账-恢复密钥-${today()}.txt`);break;case'recovery-copy':await copyValue(recoverySecret);break;case'recovery-done':closeModal();break;case'password-change':passwordChangeForm();break;case'export':{toast('正在整理数据库与附件…');const blob=await api('/api/backup',undefined,{blob:true});downloadBlob(blob,`小车台账-${profile==='demo'?'演示':'正式'}-${today()}.zip`);toast('完整备份已开始下载');break;}case'restore':restoreForm();break;case'shutdown':confirmAction('停止本地服务','数据已保存在本机。下次双击桌面“小车台账”入口即可再次打开。',async()=>{await api('/api/shutdown',{});db={};session.unlocked=false;$('#main').innerHTML=`<div class="auth-card"><div class="auth-logo">${icon('check')}</div><h1 class="auth-title">本地服务已停止</h1><p class="auth-subtitle">记录已保存在本机。你可以关闭此页面，下次双击桌面“小车台账”继续。</p></div>`;},{reason:false,submit:'停止服务'});break;}}
async function switchProfile(next){if(next===profile&&session.unlocked)return;if(!closeModal())return;closeDrawer();db={};profile=next;localStorage.setItem('car-ledger-profile',next);filters={};$('#main').innerHTML='<div class="loading"><span class="spinner"></span>正在切换台账…</div>';await load();}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){if(busy){toast('正在保存，请稍候完成后再关闭。');return;}close.dataset.close==='drawer'?closeDrawer():closeModal();return;}const nav=e.target.closest('[data-route]');if(nav){go(nav.dataset.route);return;}const profileBtn=e.target.closest('[data-profile]');if(profileBtn){switchProfile(profileBtn.dataset.profile).catch(err=>toast(err.message,true));return;}const tab=e.target.closest('[data-tab]');if(tab){inventoryTab=tab.dataset.tab;filters={};render();return;}const target=e.target.closest('[data-act]');if(target){e.preventDefault();const originalDisabled=target.disabled;target.disabled=true;Promise.resolve(dispatch(target.dataset.act,target)).catch(err=>{if(modal.open)formError(err.message);else toast(err.message,true);}).finally(()=>{if(target.isConnected)target.disabled=originalDisabled;});}});
document.addEventListener('input',e=>{const key=e.target.dataset.filter;if(!key)return;filters[key]=e.target.value;const start=e.target.selectionStart;render();const replacement=$(`[data-filter="${key}"]`);if(replacement){replacement.focus();if(start!==null)try{replacement.setSelectionRange(start,start);}catch{}}});
document.addEventListener('change',e=>{const key=e.target.dataset.filter;if(key){filters[key]=e.target.value;render();}});
document.addEventListener('submit',async e=>{if(e.target.id==='dialog-form'){e.preventDefault();if(busy||!modalSubmit)return;busy=true;setPickerBusy(true);const form=e.target,handler=modalSubmit,submit=$('[type=submit]',form);submit.disabled=true;const original=submit.innerHTML;submit.innerHTML='<span class="spinner"></span> 正在保存…';$('.form-error',form).classList.remove('visible');try{const result=await handler(new FormData(form));closeModal();if(typeof result==='function')result();}catch(err){formError(err.message);}finally{busy=false;setPickerBusy(false);if(submit.isConnected){submit.disabled=false;submit.innerHTML=original;}}}else if(e.target.id==='auth-form'){e.preventDefault();if(busy)return;busy=true;const form=e.target,fd=new FormData(form),mode=form.dataset.mode,submit=$('[type=submit]',form);submit.disabled=true;try{if(mode!=='unlock'){if(String(fd.get('password')).length<8)throw Error('密码至少需要 8 个字符');if(fd.get('password')!==fd.get('confirm_password'))throw Error('两次输入的密码不一致');}const r=await api('/api/auth/'+mode,{password:fd.get('password'),...(mode==='recover'?{recovery_key:fd.get('recovery_key')}:{})});session=await api('/api/session');lastActivity=Date.now();await refresh();if(r.recovery_key)showRecovery(r.recovery_key);toast(mode==='unlock'?'台账已解锁':'正式台账已准备好');}catch(err){formError(err.message,form);}finally{busy=false;setPickerBusy(false);if(submit.isConnected)submit.disabled=false;}}});
modal.addEventListener('cancel',e=>{if(busy){e.preventDefault();toast('正在保存，请稍候完成后再关闭。');return;}if(recoverySecret){e.preventDefault();toast('请先单独保存恢复密钥并勾选确认',true);}else {e.preventDefault();closeModal();}});
modal.addEventListener('close',()=>{accountDocumentDraft=null;clearModalPreviews();hideHoverPreview();destroyAttachmentPicker();modalSubmit=null;recoverySecret='';$('#modal-content').innerHTML='';});
let drawerBackdropStart=false;
function isDrawerBackdrop(event){const rect=drawer.getBoundingClientRect();return event.target===drawer&&(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom);}
drawer.addEventListener('pointerdown',event=>{drawerBackdropStart=drawer.open&&!modal.open&&!busy&&isDrawerBackdrop(event);});
drawer.addEventListener('click',event=>{const close=drawerBackdropStart&&!modal.open&&!busy&&isDrawerBackdrop(event);drawerBackdropStart=false;if(close){event.preventDefault();closeDrawer();}});
drawer.addEventListener('pointercancel',()=>{drawerBackdropStart=false;});
drawer.addEventListener('close',()=>{drawerBackdropStart=false;destroyPdfViews(drawer);hideHoverPreview();detailContext=null;$('#drawer-content').innerHTML='';});
$('#refresh-button').innerHTML=icon('refresh');$('#refresh-button').addEventListener('click',()=>load());$('#lock-button').addEventListener('click',()=>dispatch('lock').catch(e=>toast(e.message,true)));
function noteActivity(){if(profile==='live'&&session.unlocked&&Date.now()-lastActivity>=30*60*1000){idleLock();return;}lastActivity=Date.now();}
for(const event of ['pointerdown','keydown','input'])document.addEventListener(event,noteActivity,{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&profile==='live'&&session.unlocked&&Date.now()-lastActivity>=30*60*1000)idleLock();});
window.addEventListener('focus',()=>{if(profile==='live'&&session.unlocked&&Date.now()-lastActivity>=30*60*1000)idleLock();});
setInterval(()=>{if(profile==='live'&&session.unlocked&&Date.now()-lastActivity>=30*60*1000)idleLock();},10000);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next!==route){if(!closeModal()){history.replaceState(null,'',location.pathname+location.search+'#'+route);return;}route=next;filters={};closeDrawer();render();}});
window.addEventListener('beforeunload',event=>{if(accountDocumentDraft?.dirty){event.preventDefault();event.returnValue='';}});
load();
